# --------------------------

for n in "${numbers[@]}"
do
    echo "======================================"
    echo "Running struct_${n}"
    echo "======================================"

    if [[ ! -f struct_${n}.inp ]]; then
        echo "struct_${n}.inp not found"
        continue
    fi

    $exe struct_${n}.inp > struct_${n}.out

    J=$(grep '| J(3) =' struct_${n}.out | awk '{print $4}')

    echo "struct_${n}  ${J}" >> J-coupling.dat

    find . -maxdepth 1 -type f \
        -name "struct_${n}*" \
        ! -name "*.inp" \
        ! -name "*.xyz" \
        -delete

done

